css:
.x-tree { margin: 0; padding: 10px 16px; border-radius: var(--radius-md); background: var(--surface-sunk); font: 400 13px/19px var(--font-mono); color: var(--ink); white-space: pre; }
.x-tree i { font-style: normal; font-family: var(--font-sans); font-size: 13px; color: var(--ink-muted); }
.x-tree .later { color: var(--ink-faint); }
.x-file { border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); overflow: hidden; }
.x-file-n { padding: 8px 14px; background: var(--surface-sunk); font: 500 13px/18px var(--font-mono); }
.x-file-r { display: grid; grid-template-columns: 130px 1fr; gap: 12px; padding: 7px 14px; border-top: 1px solid var(--line); font-size: 14px; line-height: 19px; }
.x-file-r b { font-weight: 600; }
.x-file-r span { color: var(--ink-muted); }
.x-file-r.later { border-top-style: dashed; color: var(--ink-faint); }
.x-file-r.later span, .x-file-r.later b { color: var(--ink-faint); }
.x-row .x-probe { grid-template-columns: 1fr; gap: 14px; }
.sl .sl-title { max-width: 880px; }
.sl-cards.c5 { grid-template-columns: repeat(5, 1fr); }
.x-row .sl-try { grid-template-columns: 96px 1fr; gap: 10px 16px; }
.sl .x-shot img, .sl .x-shot .ph { max-height: 190px; }
.sl .x-shot img { object-fit: contain; object-position: left top; }
.sl-cards.c5 { gap: 12px; }
.is-probe .sl-cards { gap: 12px; }
.is-probe .sl-cards .sl-card { padding: 14px 16px; gap: 4px; }
.is-probe .sl-cards .sl-card h3 { font-size: 20px; line-height: 26px; }
.is-probe .sl-cards .sl-card p { font-size: 14px; line-height: 19px; }
.details .x-shot .ph { aspect-ratio: 16 / 9; }
.sl-cards.c5 .sl-card { padding: 16px; }
.sl-cards.c5 .sl-card h3 { font-size: 19px; line-height: 24px; }
.sl-cards.c5 .sl-card p { font-size: 14px; line-height: 19px; }
.x-file-r { padding: 6px 14px; }
.x-ask { font-family: var(--font-serif); font-size: 20px; line-height: 26px; margin: 0; }
.x-bad { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; font-size: 15px; line-height: 20px; color: var(--ink-muted); }
.x-bad s { text-decoration: none; padding: 3px 10px; border-radius: var(--radius-full); background: var(--surface-sunk); color: var(--ink); }
.x-code { margin: 0; padding: 14px 16px; border-radius: var(--radius-md); background: var(--surface-sunk); font: 400 13px/20px var(--font-mono); white-space: pre-wrap; }
